-- Pokédice seed data. Generated by `pnpm seed` — do not edit by hand.
-- Run AFTER the migrations (0001_init.sql, then any later ones). Safe to re-run: every insert is an upsert on a stable key.
begin;
on conflict (attacking, defending) do update set multiplier = excluded.multiplier;

on conflict (type) do update set label = excluded.label, color = excluded.color, faces = excluded.faces, description = excluded.description, upgradeable = excluded.upgradeable, counts_for_majority = excluded.counts_for_majority, sort_order = excluded.sort_order;

on conflict (dex) do update set name = excluded.name, type1 = excluded.type1, type2 = excluded.type2, base_hp = excluded.base_hp, max_hp = excluded.max_hp, speed = excluded.speed, sprite_url = excluded.sprite_url, dice = excluded.dice, rerolls = excluded.rerolls, catch_value = excluded.catch_value, evolutions = excluded.evolutions, milestones = excluded.milestones, notes = excluded.notes;

on conflict (id) do update set order_index = excluded.order_index, name = excluded.name, banner_url = excluded.banner_url, xp_to_unlock_next = excluded.xp_to_unlock_next, min_level = excluded.min_level, max_level = excluded.max_level, encounter_weights = excluded.encounter_weights, backtrack_multiplier = excluded.backtrack_multiplier, legendary_boss = excluded.legendary_boss, scales_to_team = excluded.scales_to_team, easy_mode = excluded.easy_mode, hidden = excluded.hidden, unlock_conditions = excluded.unlock_conditions, gyms = excluded.gyms;

on conflict (id) do update set name = excluded.name, sprite_url = excluded.sprite_url, team = excluded.team, role = excluded.role, badge = excluded.badge;

on conflict (id) do update set area_id = excluded.area_id, dex = excluded.dex, weight = excluded.weight, min_level = excluded.min_level, max_level = excluded.max_level;

on conflict (id) do update set area_id = excluded.area_id, trainer_id = excluded.trainer_id, weight = excluded.weight;

on conflict (id) do update set area_id = excluded.area_id, item_key = excluded.item_key, weight = excluded.weight, unique_find = excluded.unique_find, min_qty = excluded.min_qty, max_qty = excluded.max_qty;

on conflict (combo_key, level) do update set bonus = excluded.bonus, cost = excluded.cost;

on conflict (die_type, level) do update set bonus = excluded.bonus, cost = excluded.cost;

on conflict (key) do update set name = excluded.name, description = excluded.description, sprite_url = excluded.sprite_url, price = excluded.price, effect = excluded.effect, in_shop = excluded.in_shop, shop_badges = excluded.shop_badges;

on conflict (key) do update set value = excluded.value;

commit;